text:
// 5 days/week, ~45 min sessions, moderate intensity. Equipment: Resistance bands, Barbell, rack & bench, Dual adjustable pulley (cable), Dumbbells & bench, Kettlebells, Lat pulldown station, Pull-up bar.
# Week 1
// Estimated ~40 min
## Upper A
// Lower with control until elbows are just below the bench.
Bench Press, Dumbbell / 3x8 / 10kg / 120s / progress: dp(2kg, 8, 12)
// Low pulley, sit tall, pull handles to your ribs.
Seated Row, Cable / 3x8 / 20kg / 120s / progress: dp(2.5kg, 8, 12)
// Squeeze glutes, press the bar up and move your head through.
Overhead Press, Barbell / 3x8 / 20kg / 120s / progress: lp(2.5kg, 1, 0, 10%, 3, 0)
// Thighs under the pad, pull the bar to your upper chest.
Lat Pulldown, Cable / 3x8 / 25kg / 120s / progress: dp(2.5kg, 8, 12)

// Estimated ~37 min
## Lower A
// Hold the bell by the horns at your chest.
Goblet Squat, Kettlebell / 3x8 / 12kg / 120s / progress: dp(4kg, 8, 12)
// Bar over mid-foot, flat back, push the floor away.
Deadlift, Barbell / 3x8 / 40kg / 120s / progress: lp(5kg, 1, 0, 10%, 3, 0)
// Step back, front shin vertical, push through the front heel.
Reverse Lunge, Dumbbell / 3x10 / 6kg / 75s / warmup: none / progress: dp(2kg, 10, 14)
// On a step if you can, pause at the top.
Standing Calf Raise, Dumbbell / 3x10 / 10kg / 75s / warmup: none / progress: dp(2kg, 10, 14)
// Low back pressed into the floor, extend opposite arm and leg.
Dead Bug, Bodyweight / 3x8 / 0kg / 75s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}

// Estimated ~41 min
## Full Body
// Step back, front shin vertical, push through the front heel.
Reverse Lunge, Dumbbell / 3x10 / 6kg / 75s / warmup: none
// Bench at ~30°, press up and slightly back.
Incline Bench Press, Dumbbell / 3x8 / 8kg / 120s / progress: dp(2kg, 8, 12)
// Low pulley, sit tall, pull handles to your ribs.
Seated Row, Cable / 3x8 / 20kg / 120s
// Squeeze glutes, press the bar up and move your head through.
Overhead Press, Barbell / 3x8 / 20kg / 120s
// Upper back on the bench, chin tucked, squeeze at the top.
Hip Thrust, Barbell / 3x10 / 30kg / 75s / warmup: none / progress: dp(2.5kg, 10, 14)

// Estimated ~41 min
## Upper B
// Seated or standing, press up without arching your back.
Shoulder Press, Dumbbell / 3x8 / 8kg / 120s / progress: dp(2kg, 8, 12)
// Palms facing you, pull chin over the bar. Do negatives if needed.
Chin Up, Bodyweight / 3x8 / 0kg / 75s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Bench at ~30°, press up and slightly back.
Incline Bench Press, Dumbbell / 3x8 / 8kg / 120s
// Hand on the bench, pull the dumbbell to your hip.
Bent Over One Arm Row, Dumbbell / 3x8 / 12kg / 120s / progress: dp(2kg, 8, 12)
// Anchor at face height, pull toward your forehead, thumbs back.
Face Pull, Band / 3x8 / 0kg / 75s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}

// Estimated ~37 min
## Lower B
// Soft knees, slide dumbbells down your thighs, hips back.
Romanian Deadlift, Dumbbell / 3x8 / 10kg / 120s / progress: dp(2kg, 8, 12)
// Brace, sit between your hips, knees track over toes.
Squat, Barbell / 3x8 / 20kg / 120s / progress: lp(2.5kg, 1, 0, 10%, 3, 0)
// Upper back on the bench, chin tucked, squeeze at the top.
Hip Thrust, Barbell / 3x10 / 30kg / 75s / warmup: none
// Feet staggered, drop the back knee straight down.
Split Squat, Dumbbell / 3x10 / 6kg / 75s / warmup: none / progress: dp(2kg, 10, 14)
// Pulley high, kneel with the rope, crunch ribs toward hips.
Cable Crunch, Cable / 3x10 / 15kg / 75s / warmup: none / progress: dp(2.5kg, 10, 14)
